			title = "Resumo",
			text = [=[Takata Steelblade é um espadachim {link:orcs}orc{/link} que comanda a campanha da {link:horde}Horda{/link} contra os demônios da {link:desolace}Desolação{/link}. O próprio {link:thrall}Thrall{/link} aprovou a missão, e Takata a cumpre com a paciência sombria de um soldado longe de casa. Não gosta dos centauros, cuja terra precisa dividir, e gosta ainda menos dos bruxos da Horda. Mesmo assim, cumpre o seu dever, e o cumpre bem.]=],
		},
		{
			title = "Importância",
			text = [=[A campanha de Takata é uma questão de honra para a {link:horde}Horda{/link}. À medida que a {link:alliance}Aliança{/link} avança mais fundo em {link:kalimdor}Kalimdor{/link}, alguns entre eles se apressam em acreditar que a Horda fez pactos com a {link:burning-legion}Legião Ardente{/link}. Cada demônio morto na {link:desolace}Desolação{/link} por mãos orcs é uma resposta a essa acusação.]=],
		},
		{
			title = "Feitos",
			text = [=[• Conduz a luta da {link:horde}Horda{/link} contra os demônios e a {link:burning-blade}Lâmina Ardente{/link} na {link:desolace}Desolação{/link}.
• Trabalha ao lado do bruxo {link:maurin-bonesplitter}Maurin Bonesplitter{/link}, embora não confie inteiramente nele.
• Envia notícias do progresso da campanha de volta a {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Notícias de Orgrimmar",
			hint = [=[Leve notícias de Orgrimmar ao espadachim do Entreposto do Espírito que Anda.]=],
			text = [=[As ordens vieram de Keldran, de {link:orgrimmar}Orgrimmar{/link}, um estudioso da magia e de artes mais sombrias, com a bênção do Chefe Guerreiro. A {link:horde}Horda{/link} não admitiria que se dissesse que seu povo se curvava a demônios. Takata acolheu os emissários que vieram ajudar, mas não escondeu seu nojo pelo fedor da terra, nem seu desconforto com uma guerra que, no fim, também ajudava os centauros.]=],
		},
		{
			title = "O Corruptor",
			hint = [=[Ajude o espadachim a decidir quem deve enfrentar o senhor demoníaco.]=],
			text = [=[Quando a vidência de {link:maurin-bonesplitter}Maurin{/link} mostrou a imagem do {link:lord-azrethoc}Lorde Azrethoc{/link}, Takata viu de imediato que o demônio era mais forte que seu companheiro bruxo. Ansiava por enfrentar a criatura ele mesmo, mas seu posto o prendia, e abandoná-lo teria envergonhado seu clã. Assim, enviou outros para o sul, às {link:mannoroc-coven}Ruínas de Mannoroc{/link}, e quando voltaram vitoriosos, ousou esperar que a {link:horde}Horda{/link} pudesse um dia ter um lugar que chamasse de lar em segurança.]=],
		},
	},
	mentions = {
		{
			text = [=[Relações com a {link:alliance}Aliança{/link}, de {link:orgrimmar}Orgrimmar{/link}]=],
		},
		{ text = "Relações com a {link:alliance}Aliança{/link}" },
		{ text = "Conspurcado por {link:satyrs}Sátiros{/link}" },
		{
			text = [=[Relações com a {link:alliance}Aliança{/link}, o relatório a Keldran]=],
		},
		{ text = "O Corruptor" },
		{ text = "O Corruptor, a caçada a {link:lord-azrethoc}Azrethoc{/link}" },
	},
	bonds = {
		{ id = "maurin-bonesplitter", name = "Maurin Bonesplitter", note = "seu companheiro bruxo" },
		{ id = "lord-azrethoc", name = "Lorde Azrethoc", note = "inimigo" },
		{ id = "thrall", name = "Thrall", note = "seu Chefe Guerreiro" },
	},
})

