			title = "Importância",
			text = [=[A busca de Vahlarriel revela até onde chega a {link:burning-blade}Lâmina Ardente{/link}, e como até um filho dos {link:night-elves}elfos noturnos{/link} pode ser atraído pela magia que seu povo proíbe.]=],
