		},
		{
			title = "O Destino dos Malem",
			hint = [=[Tire Dalinda Malem em segurança da Fortaleza Machado do Trovão.]=],
			text = [=[{link:dalinda-malem}Dalinda{/link} voltou ao {link:nijels-point}Posto do Nijel{/link} com os próprios pés, e Vahlarriel considerou isso uma misericórdia. {link:tyranis-malem}Tyranis{/link} não voltou. Ele buscara o favor dos cultistas que o capturaram, e morreu entre eles. A vergonha de suas escolhas viajaria para casa com a irmã, e só ela teria de suportá-la diante de seu povo.]=],
		},
	},
	mentions = {
