	},
	chapters = {
		{
			title = "Uma Grande Tribo",
			hint = "Faça o que o Pária pede nos salões de Maraudon.",
			text = [=[O forasteiro entrou no túmulo e voltou com aquilo de que o Pária precisava. Ele se alegrou. Agora, disse, a grande obra podia começar. Pagou quem o ajudou e esperou que, quando se encontrassem de novo, fosse em termos muito diferentes. Ninguém sabe dizer ainda quais serão esses termos.]=],
		},
	},
	mentions = {
		{ text = "As Instruções do Pária" },
